//images.unsplash.com/photo-1507238691740-187a5b1d37b8?w=800&auto=format&fit=crop&q=80","instructor":{"name":"Alex Rivera","role":"Design Systems Lead","avatarUrl":"https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=200&auto=format&fit=crop&q=80"},"learningObjectives":["Configure Tailwind v4 CSS theme variables","Implement accessible color palettes and typography scales","Create fluid responsive designs with CSS container queries","Build reusable UI card and modal components"],"resources":[{"title":"Tailwind CSS v4 Guide","url":"https://tailwindcss.com"},{"title":"Design Tokens Cheatsheet","url":"https://example.com"}]},{"id":"3","slug":"ai-agents-and-llm-integrations","title":"Building Production AI Agents with TypeScript & Next.js","description":"Integrate LLM tool calling, streaming responses, vector embeddings, and RAG pipelines into web applications.","longDescription":"Step into modern AI engineering. Learn how to connect Large Language Models with structured tools, vector databases, and real-time streaming endpoints. Build autonomous agents that execute multi-step workflows safely.","duration":"32m 15s","level":"Advanced","category":"AI & ML","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed/82P_L7Jj0r8","thumbnailUrl":"https://images.unsplash.com/photo-1677442136019-21780ecad995?w=800&auto=format&fit=crop&q=80","instructor":{"name":"Dr. Maya Lin","role":"AI Research Engineer","avatarUrl":"https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=200&auto=format&fit=crop&q=80"},"learningObjectives":["Implement server-sent events for real-time text streaming","Design structured JSON tool-calling schemas","Set up Pinecone/pgvector search and context injection","Handle rate limiting, token caching, and fallback resilience"],"resources":[{"title":"Vercel AI SDK Docs","url":"https://sdk.vercel.ai"},{"title":"Prompt Engineering Best Practices","url":"https://example.com"}]},{"id":"4","slug":"fullstack-api-design-postgresql","title":"Scalable Backend Architecture with TypeScript & PostgreSQL","description":"Design resilient database schemas, migrations, connection pools, and high-throughput REST & GraphQL APIs.","longDescription":"Go beyond simple CRUD. Learn how to architect enterprise-grade relational databases, write clean database migrations with Prisma or Drizzle ORM, secure endpoints with JWT/OAuth, and optimize query latency.","duration":"28m 40s","level":"Intermediate","category":"Backend","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed/98BiG9bQO1s","thumbnailUrl":"https://images.unsplash.com/photo-1558494949-ef010cbdcc31?w=800&auto=format&fit=crop&q=80","instructor":{"name":"David Chen","role":"Cloud Infrastructure Architect","avatarUrl":"https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=200&auto=format&fit=crop&q=80"},"learningObjectives":["Structure ACID-compliant PostgreSQL tables and indexes","Implement connection pooling with PgBouncer / Neon","Create secure role-based access control (RBAC) middleware","Benchmark and profile slow queries"],"resources":[{"title":"PostgreSQL Performance Guide","url":"https://postgresql.org"},{"title":"Database Schema Templates","url":"https://example.com"}]},{"id":"5","slug":"fullstack-saas-architecture","title":"Building a Complete SaaS: Auth, Billing & Multi-Tenancy","description":"End-to-end walkthrough of building and launching a production-ready SaaS application with Stripe and auth.","longDescription":"From blank repo to first paying customer: learn subscription billing webhooks, multi-tenant workspace isolation, team invitations, transactional emails, and zero-downtime CI/CD deployment pipelines.","duration":"45m 20s","level":"Advanced","category":"Fullstack","youtubeEmbedUrl":"https://www.youtube-nocookie.com/embed/1vR3ST946Q8","thumbnailUrl":"https://images.unsplash.com/photo-1460925895917-afdab827c52f?w=800&auto=format&fit=crop&q=80","instructor":{"name":"Sarah Jenkins","role":"Principal Frontend Architect","avatarUrl":"http